const date = (value: unknown) => { if (!value) return '—'; const d = new Date(String(value)); return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short'}).format(d); };
