const asObject = (value: unknown): Row => value && typeof value === 'object' && !Array.isArray(value) ? value as Row : {};

class ApiError extends Error { constructor(message:string,public status:number) {super(message);} }
async function api<T>(path:string,method='GET',body?:unknown):Promise<T> {
  const headers:Record<string,string> = {};
  if(method!=='GET') { const csrf = await fetch('/api/auth/csrf',{credentials:'same-origin',cache:'no-store'}); if(!csrf.ok) throw new ApiError('Güvenlik oturumu alınamadı. Sayfayı yenileyin.',csrf.status); const token = await csrf.json(); headers['X-CSRF-Token']=token.csrf_token; }
  if(body!==undefined && !(body instanceof FormData)) headers['Content-Type']='application/json';
  const response = await fetch(`/api${path}`,{method,headers,credentials:'same-origin',cache:'no-store',body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});
  const text = await response.text(); let data:unknown; try { data=text?JSON.parse(text):{}; } catch { data={detail:'Sunucu beklenen yanıtı vermedi.'}; }
  if(!response.ok) { const detail=asObject(data).detail; throw new ApiError(typeof detail==='string'?detail:Array.isArray(detail)?detail.map(d=>label(asObject(d).msg)).join(' · '):`İşlem tamamlanamadı (${response.status}).`,response.status); }
  return data as T;
}
