 {edit&&<AccountForm account={edit==='new'?null:edit} onClose={()=>setEdit(null)} onSave={async(data,logo,media)=>{const uploadErrors:string[]=[];const result=await api<Account>(edit==='new'?'/accounts':`/accounts/${edit.id}`,edit==='new'?'POST':'PATCH',data);if(logo){const f=new FormData();f.append('file',logo);try{await api(`/accounts/${result.id}/logo`,'POST',f);}catch(e){uploadErrors.push(`Logo yüklenemedi: ${(e as Error).message}`);}}for(const [kind,file] of Object.entries(media)){if(!file)continue;const form=new FormData();form.append('file',file);try{await api(`/accounts/${result.id}/media?kind=${kind}`,'POST',form);}catch(e){uploadErrors.push(`${kind} dosyası yüklenemedi: ${(e as Error).message}`);}}setEdit(null);setToast(uploadErrors.length?'Hesap kaydedildi; bazı dosyalar yüklenemedi.':'Hesap ayarları kaydedildi.');await refresh(true);setPage('accounts');window.location.hash='accounts';await openAccount(result.id);if(uploadErrors.length)setError(uploadErrors.join(' · '));}}/>}
